parameters.jsCode:
// Normalise the Meta Cloud API payload into one flat object.
// Timezone-safe via Luxon in Europe/Madrid, same convention as the voice workflow.
const TZ = 'Europe/Madrid';
const now = DateTime.now().setZone(TZ);

const body = $json.body ?? $json;
const value = body?.entry?.[0]?.changes?.[0]?.value ?? body;
const msg = value?.messages?.[0] ?? {};
const contact = value?.contacts?.[0] ?? {};

// Mon-Thu 10-20, Fri 10-14, closed Sat/Sun (Luxon: 1=Mon ... 7=Sun).
const OPEN = { 1: [10, 20], 2: [10, 20], 3: [10, 20], 4: [10, 20], 5: [10, 14] };
const todays = OPEN[now.weekday];
const isOpen = !!todays && now.hour >= todays[0] && now.hour < todays[1];

return [{
  json: {
    wa_id: msg.from ?? contact.wa_id ?? null,
    message_id: msg.id ?? null,
    type: msg.type ?? 'unknown',
    text: msg.text?.body ?? msg.button?.text ?? msg.interactive?.list_reply?.title ?? '',
    profile_name: contact.profile?.name ?? null,
    // Injected into the system prompt so the agent never guesses the date.
    now_madrid: now.toISO({ suppressMilliseconds: true }),
    now_human: now.setLocale('es').toFormat("cccc d 'de' LLLL, HH:mm"),
    clinic_is_open: isOpen
  }
}];

